-- Matriz release 1 schema (see docs/database.md).
-- Conventions: UUID primary keys generated by the application, timestamps in
-- UTC (timestamptz), enums as constrained text. Text is trimmed by the backend;
-- the checks below are a last line of defence.

-- Trigram index support for case-insensitive "contains" search on project names.
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- Identity & Access -----------------------------------------------------------
CREATE TABLE users (
    id                    uuid         PRIMARY KEY,
    email                 varchar(254) NOT NULL,
    name                  varchar(100) NOT NULL,
    password_hash         varchar(255) NOT NULL,
    is_admin              boolean      NOT NULL DEFAULT false,
    is_active             boolean      NOT NULL DEFAULT true,
    failed_login_attempts integer      NOT NULL DEFAULT 0,
    locked_until          timestamptz,
    created_at            timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT users_email_not_blank CHECK (btrim(email) <> ''),
    CONSTRAINT users_name_not_blank CHECK (btrim(name) <> ''),
    CONSTRAINT users_failed_login_attempts_non_negative CHECK (failed_login_attempts >= 0)
);

-- Email is unique regardless of case.
CREATE UNIQUE INDEX users_email_lower_uk ON users (lower(email));

-- Projects --------------------------------------------------------------------
CREATE TABLE project (
    id          uuid          PRIMARY KEY,
    name        varchar(100)  NOT NULL,
    description varchar(1000),
    owner_id    uuid          NOT NULL REFERENCES users (id),
    status      varchar(20)   NOT NULL DEFAULT 'ACTIVE',
    archived_at timestamptz,
    created_at  timestamptz   NOT NULL DEFAULT now(),
    updated_at  timestamptz   NOT NULL DEFAULT now(),
    CONSTRAINT project_name_length CHECK (char_length(btrim(name)) BETWEEN 3 AND 100),
    CONSTRAINT project_status_valid CHECK (status IN ('ACTIVE', 'ARCHIVED')),
    CONSTRAINT project_archived_at_matches_status
        CHECK ((status = 'ARCHIVED') = (archived_at IS NOT NULL))
);

CREATE INDEX project_owner_idx ON project (owner_id);
CREATE INDEX project_name_trgm_idx ON project USING gin (lower(name) gin_trgm_ops);

CREATE TABLE project_member (
    project_id uuid        NOT NULL REFERENCES project (id),
    user_id    uuid        NOT NULL REFERENCES users (id),
    role       varchar(20) NOT NULL,
    joined_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT project_member_pk PRIMARY KEY (project_id, user_id),
    CONSTRAINT project_member_role_valid CHECK (role IN ('MANAGER', 'MEMBER'))
);

CREATE INDEX project_member_user_idx ON project_member (user_id);

-- Tasks -----------------------------------------------------------------------
CREATE TABLE task (
    id            uuid          PRIMARY KEY,
    project_id    uuid          NOT NULL REFERENCES project (id),
    title         varchar(150)  NOT NULL,
    description   varchar(2000),
    status        varchar(20)   NOT NULL DEFAULT 'TODO',
    priority      varchar(20)   NOT NULL DEFAULT 'MEDIUM',
    created_by_id uuid          NOT NULL REFERENCES users (id),
    version       integer       NOT NULL DEFAULT 1,
    created_at    timestamptz   NOT NULL DEFAULT now(),
    updated_at    timestamptz   NOT NULL DEFAULT now(),
    CONSTRAINT task_title_length CHECK (char_length(btrim(title)) BETWEEN 3 AND 150),
    CONSTRAINT task_status_valid CHECK (status IN ('TODO', 'IN_PROGRESS', 'DONE')),
    CONSTRAINT task_priority_valid CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH')),
    CONSTRAINT task_version_positive CHECK (version >= 1)
);

-- Per-status counts (dashboard, project progress) and default list order.
CREATE INDEX task_project_status_idx ON task (project_id, status);
CREATE INDEX task_project_created_idx ON task (project_id, created_at DESC);
CREATE INDEX task_created_by_idx ON task (created_by_id);

CREATE TABLE task_assignee (
    task_id        uuid        NOT NULL REFERENCES task (id) ON DELETE CASCADE,
    user_id        uuid        NOT NULL REFERENCES users (id),
    assigned_at    timestamptz NOT NULL DEFAULT now(),
    assigned_by_id uuid        NOT NULL REFERENCES users (id),
    -- A user is assigned at most once per task.
    CONSTRAINT task_assignee_pk PRIMARY KEY (task_id, user_id)
);

CREATE INDEX task_assignee_user_idx ON task_assignee (user_id);

-- Comments --------------------------------------------------------------------
CREATE TABLE comment (
    id         uuid          PRIMARY KEY,
    task_id    uuid          NOT NULL REFERENCES task (id) ON DELETE CASCADE,
    author_id  uuid          NOT NULL REFERENCES users (id),
    body       varchar(2000) NOT NULL,
    created_at timestamptz   NOT NULL DEFAULT now(),
    CONSTRAINT comment_body_not_blank CHECK (btrim(body) <> '')
);

CREATE INDEX comment_task_created_idx ON comment (task_id, created_at);
CREATE INDEX comment_author_idx ON comment (author_id);
